content.text:
            j = bl(ekeys, q)
            if j < len(ekeys) and ekeys[j] == q:
                ni = echild[j]
            else:
                break
        append({'hop': besth, 'prefix_length': bestl})
    return {'status': 'ok', 'answers': answers}


# ---------------------------------------------------------------------------
# JSON transport
# ---------------------------------------------------------------------------

def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d


def _bad_const(name):
    raise Invalid()


# A valid request never contains more than about 1.2 million JSON structural
# characters (16 stages x 2048 nodes/edges, 2048 rules, 20000 addresses), so a
# line whose raw count of ',', ':', '[' and '{' characters exceeds this bound
# by a wide margin cannot be a valid request.  Rejecting such lines up front
# keeps a hostile 32 MiB line from exhausting memory (or time) inside the JSON
# parser, while never rejecting a valid request however it is spelled.
_MAX_STRUCT = 3000000


def parse_request(line):
    """Strict JSON parse of one request line; raises Invalid on any problem."""
    if (line.count(',') + line.count(':') +
            line.count('[') + line.count('{')) > _MAX_STRUCT:
        raise Invalid()
    try:
        return json.loads(line, object_pairs_hook=_pairs,
                          parse_constant=_bad_const)
    except Invalid:
        raise
    except (ValueError, RecursionError, MemoryError, TypeError, OverflowError):
        raise Invalid()


def handle(req):
    if type(req) is not dict:
        raise Invalid()
    op = req.get('op')
    if op == 'compile':
        if frozenset(req.keys()) != frozenset(('op', 'fib', 'capacities', 'max_stride')):
            raise Invalid()
        return handle_compile(req)
    if op == 'lookup':
        if frozenset(req.keys()) != frozenset(('op', 'image', 'addresses')):
            raise Invalid()
        return handle_lookup(req)
    raise Invalid()


def main():
    stdin = sys.stdin.buffer
    stdout = sys.stdout
    dumps = json.JSONEncoder(separators=(',', ':')).encode
    while True:
        raw = stdin.readline()
        if not raw:
            break
        try:
            line = raw.decode('utf-8')
        except UnicodeDecodeError:
            resp = {'status': 'invalid'}
        else:
            try:
                resp = handle(parse_request(line))
            except Invalid:
                resp = {'status': 'invalid'}
            except (MemoryError, RecursionError):
                resp = {'status': 'invalid'}
            except Exception:
                traceback.print_exc(file=sys.stderr)
                resp = {'status': 'invalid'}
        stdout.write(dumps(resp))
        stdout.write('\n')
        stdout.flush()


